const quandoFoi = (ms) => { const d = new Date(ms - 4 * 3600e3); const p = (n) => String(n).padStart(2, '0'); return ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb'][d.getUTCDay()] + ' ' + p(d.getUTCDate()) + '/' + p(d.getUTCMonth() + 1) + ' ' + p(d.getUTCHours()) + ':' + p(d.getUTCMinutes()); };
let lista = []; try { lista = JSON.parse($('Ler feitos').first().json.feitos || '[]'); } catch (e) {}
const agora = Date.now();
lista = (Array.isArray(lista) ? lista : []).filter((f) => f && agora - f.em < 36 * 3600e3);
const texto = lista.length ? lista.map((f) => '- ' + quandoFoi(f.em) + ' ' + f.t + ' (' + f.a + ') → ' + f.r).join('\n') : '(nada ainda)';
const podeForcar = lista.some((f) => agora - f.em < 30 * 60e3 && /NÃO (MARQUEI|REAGENDEI|MUDEI)/.test(f.r)) ? 'sim' : '';
return [{ json: { lista, texto, podeForcar, agora: '[' + quandoFoi(agora) + ']' } }];

const ag = $('Agente assistente').first().json;
const ctx = $('Contexto').first().json;
const agora = Date.now();
let texto = String(ag.output || '').trim().replace(/\*\*([^*\n]+?)\*\*/g, '*$1*');
const passos = Array.isArray(ag.intermediateSteps) ? ag.intermediateSteps : [];
const lerResposta = (o) => { const t = typeof o === 'string' ? o : JSON.stringify(o || ''); try { const j = JSON.parse(t); const x = Array.isArray(j) ? j[0] : j; if (x && typeof x.resposta === 'string') return x.resposta; } catch (e) {} return t; };
const ENVIO = ["chamar_cliente","avisar_cliente"], ESCRITA = ["chamar_cliente","avisar_cliente","resultado_avaliacao","status_atendimento","registrar_atendimento","anotar","liberar_horario","marcar_horario","ajustar_duracao","reagendar","atrasar_agenda","concluir","chegou","excluir_horario","bloquear_dias","desbloquear_dias","bloquear_horario","desbloquear_horario","pausar_ia","editar_cliente","cadastrar_cliente","combinar_retorno","guardar_regra","tirar_regra","ensinar_resposta","tirar_resposta"];
const ok = (r) => /^\s*OK\b/i.test(r);
const resumo = (i) => Object.entries(i || {}).filter(([k, v]) => !['acao', 'pedido_por', 'pode_forcar'].includes(k) && v !== '' && v != null && String(v) !== '0').map(([k, v]) => k + '=' + String(v).slice(0, 90)).join('; ');
const novos = passos.filter((s) => ESCRITA.includes(s.action?.tool)).map((s) => ({ em: agora, t: s.action.tool, a: resumo(s.action.toolInput), r: lerResposta(s.observation).replace(/\s+/g, ' ').slice(0, 240) }));
const antes = Array.isArray(ctx.lista) ? ctx.lista : [];
const feitos = antes.concat(novos).slice(-40);
const haPouco = (nomes, min) => antes.some((f) => nomes.includes(f.t) && ok(f.r) && agora - f.em < min * 60e3);
const enviou = novos.some((f) => ENVIO.includes(f.t) && ok(f.r));
const gravou = novos.some((f) => ok(f.r));
const semNegar = texto.replace(/\b(n[ãa]o|nem|nunca)\s+(\S+\s+){0,2}?(avisei|mandei|enviei|anotei|marquei|gravei|salvei|registrei|mudei|cancelei|remarquei|reagendei|bloqueei|cadastrei|conclu[ií]|liberei|apaguei|guardei)\b/gi, '');
const afirma = /\b(avisei|mandei|enviei)\b|mensagem (foi )?enviada|já (falei|chamei) com ela/i.test(semNegar);
const afirmaGravou = /\b(anotei|marquei|gravei|salvei|registrei|mudei|cancelei|remarquei|reagendei|bloqueei|cadastrei|conclu[ií]|liberei|apaguei|guardei)\b/i.test(semNegar);
const passado = /\b(ontem|mais cedo|já tinha|já estava|já está)\b/i.test(texto);
let corrigida = false; const original = texto;
if (afirma && !enviou && !haPouco(ENVIO, 20) && !passado) { texto = ('Ainda não mandei nada pra ela, ' + $('Loja').first().json.dona + '. Quer que eu mande agora? Me confirma o texto que eu envio.'); corrigida = true; }
else if (afirmaGravou && !gravou && !haPouco(ESCRITA, 180) && !passado) { texto = ('Opa, ainda não gravei isso, ' + $('Loja').first().json.dona + '. Posso gravar agora?'); corrigida = true; }
const promessa = (f) => /fico de olho|fico (no aguardo|aguardando)|vou ficar de olho/i.test(f) || (/(te aviso|eu aviso|aviso voc[eê]|te falo|te conto|te chamo)/i.test(f) && /respond/i.test(f));
if (!corrigida) texto = texto.split('\n').map((l) => l.split(/(?<=[.!?…])\s+/).filter((f) => !promessa(f)).join(' ')).join('\n').replace(/\n{3,}/g, '\n\n').trim();
texto = texto.replace(/^\s*\[(dom|seg|ter|qua|qui|sex|sáb) \d\d\/\d\d \d\d:\d\d\]\s*/i, '');
if (!texto) texto = ag.output ? '👍' : 'Desculpa, deu um erro aqui. Pode repetir?';
const nota = corrigida ? JSON.stringify({ type: 'ai', data: { content: ('(Nota do sistema: a resposta acima NÃO chegou à ' + $('Loja').first().json.dona + ', porque dizia que algo foi feito sem a ferramenta ter rodado. Nada foi gravado nem enviado. Ela recebeu: "') + texto + '")', additional_kwargs: {}, response_metadata: {}, tool_calls: [], invalid_tool_calls: [] } }) : '';
return [{ json: { texto: texto.replace(/\*\*(.+?)\*\*/g, '*$1*'), corrigida, original: corrigida ? original : '', nota, feitos: JSON.stringify(feitos), ferramentas: passos.map((s) => s.action?.tool) } }];

const passos = $('Agente assistente').first().json.intermediateSteps || [];
const lerResposta = (o) => { const t = typeof o === 'string' ? o : JSON.stringify(o || ''); try { const j = JSON.parse(t); const x = Array.isArray(j) ? j[0] : j; if (x && typeof x.resposta === 'string') return x.resposta; } catch (e) {} return t; };
const fim8 = (t) => String(t || '').replace(/\D/g, '').slice(-8);
const tels = passos.filter((s) => ['chamar_cliente', 'avisar_cliente'].includes(s.action?.tool)).map((s) => lerResposta(s.observation))
  .map((r) => (/^\s*OK\b[^(]*\(tel\. (\d+)\)/.exec(r) || [])[1]).filter(Boolean).map(fim8);
if (!tels.length) return [];
const abertos = $('Ler pedidos abertos').first().json || {};
return Object.entries(abertos).filter(([k, v]) => { try { const p = typeof v === 'string' ? JSON.parse(v) : v; return /^pedido:/.test(k) && p && tels.includes(fim8(p.telefone)); } catch (e) { return false; } })
  .map(([k]) => ({ json: { chave: k } }));

const dela = String($('Juntar mensagens').first().json.texto || '');
const texto = String($json.texto || '');
const pausa = Math.min(4, 1.5 + dela.length / 120 + (dela.startsWith('[áudio]') ? 1 : 0));
const delay = Math.round(Math.min(8000, Math.max(2000, texto.length * 30)));
return [{ json: { pausa, delay } }];

// lista do Redis: [0] = mais nova (a memória grava com LPUSH)
const lista = [].concat($input.first().json.memoria || []);
const quebra = (s) => { try { const m = JSON.parse(s); return m.type === 'tool' || (m.type === 'ai' && (m.data?.tool_calls || []).length > 0); } catch (e) { return false; } };
let fim = Math.min(lista.length, 40);
if (!fim || !quebra(lista[fim - 1])) return [{ json: { cortar: false }, pairedItem: 0 }];
// recua até uma mensagem dela: o histórico começa como uma conversa normal
const dela = (s) => { try { return JSON.parse(s).type === 'human'; } catch (e) { return false; } };
while (fim > 0 && !dela(lista[fim - 1])) fim--;
// toda interação começa com a mensagem dela, então sempre há um ponto bom; sem ele, não mexe
if (!fim) return [{ json: { cortar: false }, pairedItem: 0 }];
return [{ json: { cortar: true, de: lista.length, para: fim, manter: lista.slice(0, fim) }, pairedItem: 0 }];

// Ficha da loja deste atendimento (motor único). Tudo o que muda de uma loja para outra sai daqui.
const bruto = $('Buscar loja').first().json;
const f = typeof bruto === 'string' ? JSON.parse(bruto || 'null') : bruto;
if (!f || !f.empresa_id) return [];
const sem9 = (n) => { const d = String(n).replace(/\D/g, ''); return /^55\d{2}9\d{8}$/.test(d) ? d.slice(0, 4) + d.slice(5) : d; };
const lista = (v) => (Array.isArray(v) ? v : String(v || '').split(',')).map((s) => String(s).trim()).filter(Boolean);
const dona = String(f.dona || 'responsável').trim();
// Trava de teste: números com e sem o 9 (o principal compara como o WhatsApp manda; as rotinas, sem o 9).
// Loja ainda não liberada pela agência (config.ia.liberada) e sem lista: ninguém recebe, só a dona.
let permitidos = [...new Set(lista(f.permitidos).flatMap((n) => [n.replace(/\D/g, ''), sem9(n)]).filter(Boolean))];
if (f.liberada !== true && !permitidos.length) permitidos = ['0'];
if (f.liberada === true) permitidos = [];
return [{ json: {
  empresa_id: f.empresa_id, nome: f.nome || '', nicho: f.nicho || '', instancia: f.instancia || '',
  dona, dona_maiuscula: dona.toUpperCase(), nome_maiusculo: String(f.nome || '').toUpperCase(), cidade: f.cidade || '', fuso: f.fuso || 'America/Cuiaba',
  assist: lista(f.assist).join(','), assist_sem9: lista(f.assist).map(sem9).join(','),
  permitidos: permitidos.join(','), catalogo_link: f.catalogo_link || '',
  // tempo mínimo que cada cliente ocupa na agenda (config.ia.bloco_min); 0 = vale o tempo de cada serviço
  bloco_min: Number.isInteger(Number(f.bloco_min)) && Number(f.bloco_min) >= 30 && Number(f.bloco_min) <= 480 ? Number(f.bloco_min) : 0,
  // a ficha passa de um workflow para outro (loja_json) e é lida de novo por este mesmo código: liberada vai junto
  liberada: f.liberada === true,
  // teto de conversas do mês (supabase/048): no_limite = a loja chegou ao teto; conversa_barrada = além disso,
  // quem mandou esta mensagem ainda não falou com a IA hoje (conversa nova)
  limite_mes: f.limite_mes ?? null, uso_mes: f.uso_mes ?? null, no_limite: f.no_limite === true, conversa_barrada: f.conversa_barrada === true,
} }];
